import{_ as t,o as e,c as r,a8 as s}from"./chunks/framework.BWjTbCIc.js";const d=JSON.parse('{"title":"汇基书院（东九龙） · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-c10c51a8","school_zh":"汇基书院（东九龙）","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"汇基书院（东九龙） · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-UCCKE-FIRST"],"rounds":["r1"]},"headers":[],"relativePath":"reports/school-c10c51a8/s1/2022-23-interview.md","filePath":"reports/school-c10c51a8/s1/2022-23-interview.md"}'),a={name:"reports/school-c10c51a8/s1/2022-23-interview.md"};function p(n,o,c,l,i,g){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="汇基书院-东九龙-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">汇基书院（东九龙） · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#汇基书院-东九龙-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;汇基书院（东九龙） · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-c10c51a8">← 返回汇基书院（东九龙）资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-uccke-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-uccke-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-uccke-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 个人英语为主，小组粤语或英语</p><p><strong>个人与小组环节</strong></p><p>个人面谈结合英语自我介绍、朗读及追问，小组讨论另行安排。组员有3人、4人或原定7人而实际4人的版本；一组讨论限10分钟，按座位轮流发言再回答老师。某次全程下午2时30分至4时，包含等候。</p></blockquote><blockquote><p><strong>个人面谈：</strong> 英语为主，部分兴趣问答用中文</p><p><strong>朗读与个人经历</strong></p><p>朗读一篇或其中一段，老师可能在中途叫停；有版本继续问理解题，也有只朗读。自我介绍后约2至4题或更多追问，涉及学业强弱、娱乐、择校、书籍、通勤、居住地区及小学距离。</p><p><strong>活动与选择</strong></p><p>按课外活动证书问学习中最具挑战、最深刻或开心的经历，例如辩论。也有戏剧扮演角色及其特征、喜欢国际象棋哪个棋子及原因。若好友借功课抄会怎样处理；最想见哪位历史人物，另有“到未来想见谁”的开放题。</p><p><strong>日常生活延伸</strong></p><p>了解英文名字的由来、喜欢什么花、新年怎样过及喜欢哪道年菜；有养猫且喜欢阅读的学生被追问平日陪宠物还是看书更多。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 粤语为多份明确；胶袋征费亦有英语版本</p><p><strong>环保与阅读</strong></p><p>一元胶袋征费对商户、消费者的影响及如何保持绿色生活；电子书的好坏、对学生影响、学校应否使用推广，以及自己更喜欢实体还是电子阅读。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 粤语或中文</p><p><strong>运动与校园安排</strong></p><p>全民运动日能否推广运动、政府还有什么措施、如何帮助家人养成运动习惯；是否赞成增加体育课时间并延迟放学；小学生应否使用手机。</p><p><strong>社会议题</strong></p><p>人口老化对香港的影响、是否赞成立法要求子女照顾长者、分享一次关怀长者的经历；“躺平”现象出现的原因及影响。</p></blockquote><blockquote><p><strong>家长交流：</strong> 语言未注明</p><p><strong>择校与提问</strong></p><p>部分家长另参加与校长的交流，由家长举手分享报读原因并提问，开始及结束有祈祷。</p></blockquote>',13)])])}const h=t(a,[["render",p]]);export{d as __pageData,h as default};
